using namespace std;
int n = 7;
int g[7][7];
bool seen[7];
void dfs(int u) {
  seen[u] = true;
  for (int v = 0; v < n; v++)
    if (g[u][v] == 1 && !seen[v]) dfs(v);
}
int main() {
  for (int i = 0; i < 7; i++) {
    seen[i] = false;
    for (int j = 0; j < 7; j++) g[i][j] = 0;
  }
  g[0][1] = g[1][0] = 1;
  g[1][2] = g[2][1] = 1;
  g[3][4] = g[4][3] = 1;
  int comps = 0;
  for (int i = 0; i < n; i++)
    if (!seen[i]) { dfs(i); comps++; }
  cout << comps << endl;
  return 0;
}
